<?php namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\Setting;use Illuminate\Http\Request;class SettingsController extends Controller{public function index(){return view('admin.settings.index',['settings'=>Setting::pluck('value','key')]);}public function update(Request $r){$d=$r->validate(['whatsapp_number'=>'nullable|string|max:30','shop_address'=>'nullable|string|max:500','google_maps_link'=>'nullable|url|max:1000','business_hours'=>'nullable|string|max:500','phone_number'=>'nullable|string|max:30','google_analytics_id'=>'nullable|string|max:100','meta_pixel_id'=>'nullable|string|max:100','maintenance_mode'=>'nullable|boolean']);$d['maintenance_mode']=$r->boolean('maintenance_mode') ? '1' : '0';foreach($d as $k=>$v)Setting::updateOrCreate(['key'=>$k],['value'=>$v]);return back()->with('status','Store settings updated.');}}
